function toLocked(svg: string): string {
  return svg
    .split(FOREST).join(LOCKED_DISC)
    .split(LIME).join(LOCKED_MOTIF)
    .split(CREAM).join(LOCKED_MOTIF)
}

const FILLED_LOCKED: Record<string, string> = Object.fromEntries(
  Object.entries(FILLED).map(([code, svg]) => [code, toLocked(svg)]),
)

/** True si el code tiene ícono RELLENO estilo marca. */
export function hasFilledAchievementIcon(code: string): boolean {
  return code in FILLED
}

/** Ícono relleno self-contained (trae su fondo forest). `earned=false` → medalla
 *  gris (locked). Renderealo en un contenedor con `overflow: 'hidden'` +
 *  borderRadius para recortar el cuadrado forest a círculo. */
export function FilledAchievementIcon({
  code,
  size = 52,
  earned = true,
}: {
  code: string
  size?: number
  earned?: boolean
}) {
  const xml = (earned ? FILLED : FILLED_LOCKED)[code]
  if (!xml) return null
  return <SvgXml xml={xml} width={size} height={size} />
}
